import { authorityKeyId } from '../../../src/v2/identifiers.js';
import type { AssetDescriptor, AuthorityKeyRecord, RSAKeyset } from '../../../src/v2/models.js';
import { validateAssetAuthorityBinding, validateAuthorityKeyRecord, validateKeysetAuthorityBinding, V2ValidationError } from '../../../src/v2/validator.js';

const b = (n: number, size = 32) => new Uint8Array(size).fill(n); const rootSig = new Uint8Array([1]);
const identity = { namespace_id: b(1), role: 'issuer-authority' as const, public_key: b(2), not_before_epoch: 1, not_after_epoch: 10, predecessor_id: null };
const record: AuthorityKeyRecord = { ...identity, key_id: authorityKeyId(identity), root_signature: rootSig };
validateAuthorityKeyRecord(record);
const policy = { epoch_seconds: 3600, max_lifetime_epochs: 24, boundary: 'exclusive' as const }; const descriptor: AssetDescriptor = { issuer: b(1), asset_code: 'FIX', unit: 'unit', decimals: 2, policy_digest: new Uint8Array(32), expiry_policy: policy, asset_id: new Uint8Array(32), issuer_signature: rootSig };
import { assetId, policyDigest, keysetId } from '../../../src/v2/identifiers.js'; descriptor.policy_digest = policyDigest(policy); descriptor.asset_id = assetId({ issuer: descriptor.issuer, asset_code: descriptor.asset_code, unit: descriptor.unit, decimals: descriptor.decimals, policy_digest: descriptor.policy_digest, expiry_policy: policy });
const keyIdentity = { issuer_id: b(1), asset_id: descriptor.asset_id, spend_domain: b(3), denomination: 10, issuance_epoch: 1, expiry_epoch: 2, modulus: b(4, 384), public_exponent: 65537 as const, suite: 'RSABSSA-SHA384-PSS-Randomized' as const, authority_key_id: record.key_id }; const keyset: RSAKeyset = { ...keyIdentity, keyset_id: keysetId(keyIdentity), authority_signature: rootSig };
validateAssetAuthorityBinding(descriptor, record); validateKeysetAuthorityBinding(keyset, descriptor, record);
const expect = (mutate: () => void, check: () => void, category: string) => { mutate(); try { check(); throw new Error('accepted invalid authority record'); } catch (error) { if (!(error instanceof V2ValidationError) || error.category !== category) throw error; } };
expect(() => { record.role = 'witness-authority'; }, () => validateAuthorityKeyRecord(record), 'hash-binding'); record.role = 'issuer-authority';
expect(() => { record.public_key = b(2, 31); }, () => validateAuthorityKeyRecord(record), 'schema'); record.public_key = b(2);
expect(() => { record.key_id = b(8); }, () => validateAuthorityKeyRecord(record), 'hash-binding'); record.key_id = authorityKeyId(identity);
expect(() => { record.not_after_epoch = 1; }, () => validateAuthorityKeyRecord(record), 'time'); record.not_after_epoch = 10;
expect(() => { record.predecessor_id = b(9, 31); }, () => validateAuthorityKeyRecord(record), 'schema'); record.predecessor_id = null;
expect(() => { descriptor.issuer = b(8); }, () => validateAssetAuthorityBinding(descriptor, record), 'hash-binding'); descriptor.issuer = b(1);
expect(() => { keyset.authority_key_id = b(8); }, () => validateKeysetAuthorityBinding(keyset, descriptor, record), 'hash-binding');
console.log('V2 authority-record binding tests: passed');
